async function api(path, options = {}) {
  const token = typeof window !== 'undefined' ? localStorage.getItem('parkease_token') : '';
  const response = await fetch(`/api${path}`, { ...options, headers: { 'Content-Type': 'application/json', ...(token ? { Authorization: `Bearer ${token}` } : {}), ...options.headers }, ...(options.body ? { body: JSON.stringify(options.body) } : {}) });
  const data = await response.json().catch(() => ({ error: 'The API is unavailable. Start the backend and try again.' }));
  if (!response.ok) throw new Error(data.error || 'Could not complete this request.');
  return data;
}

